-- 800: organization -> actor in the database's own names, back again (GHUS, 25 Nov 2026).
--
-- Generated by migrations/proposed/actor_800/generate.py from a local copy of production
-- taken just before; see that folder's README for the apply sequence.
--
--   * The 26 actor_* stand-in views that 720 left are dropped (views only: no data).
--   * 20 tables and 7 views named organization take the actor names again, with
--     their 47 columns named organization, and the constraint, index, trigger and policy
--     names on them. organization_template (730) becomes actor_template.
--   * The 9 functions 720/790 wrote with organization names are rewritten with
--     the actor names (and renamed where their name says organization).
--   * Everything built since 720 stays: the one organization table of 790 (now actor), the
--     columns 750/770 removed stay removed, the event fields of 740, the template view of 730.
--   * Not changed: the category label people read ("Company / Corporate Organization"),
--     column comments, and data.
--
-- One transaction: any failure changes nothing. Refuses unless the catalog is exactly the
-- one this was generated from.

BEGIN;
SET LOCAL lock_timeout = '15s';

DO $guard$
DECLARE found text; fns text; stand text;
BEGIN
    IF to_regclass('compass.migration_snapshot') IS NULL THEN
        RAISE EXCEPTION '800 refused: compass.migration_snapshot is missing';
    END IF;
    IF EXISTS (SELECT 1 FROM public.architecture_v2_migration_ledger WHERE migration_id = '800') THEN
        RAISE EXCEPTION '800 refused: already in the ledger';
    END IF;
    IF (SELECT migration_id FROM public.architecture_v2_migration_ledger ORDER BY applied_at DESC LIMIT 1)
       IS DISTINCT FROM '790' THEN
        RAISE EXCEPTION '800 refused: a migration was applied after 790; regenerate 800';
    END IF;
    SELECT string_agg(relname || ':' || relkind::text, ', ' ORDER BY relkind, relname) INTO found
      FROM pg_class WHERE relnamespace = 'public'::regnamespace
       AND relname LIKE '%organization%' AND relkind IN ('r','v','m','p');
    IF found IS DISTINCT FROM 'hub_organization:r, hub_organization_removed:r, organization:r, organization_category_definition:r, organization_category_migration_audit:r, organization_category_type_definition:r, organization_evaluation:r, organization_fact:r, organization_fact_current_pointer:r, organization_location:r, organization_merge_log:r, organization_person:r, organization_ranking:r, organization_relevance:r, organization_sector:r, organization_strategic_connection_check:r, organization_topic:r, organization_update_subscription:r, organization_update_subscription_run:r, organization_verification_event:r, organization_descendant_edge:v, organization_descendants:v, organization_fact_current:v, organization_fact_current_v2:v, organization_fact_history:v, organization_read:v, organization_template:v' THEN
        RAISE EXCEPTION '800 refused: the relations named organization differ from the reviewed ones: %', found;
    END IF;
    SELECT string_agg(relname, ',' ORDER BY relname) INTO stand
      FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relkind = 'v'
       AND relname = ANY ('{hub_actor,hub_actor_removed,actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_evaluation,actor_fact,actor_fact_current_pointer,actor_location,actor_merge_log,actor_person,actor_ranking,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event,actor_descendant_edge,actor_descendants,actor_fact_current,actor_fact_current_v2,actor_fact_history,actor_read,actor_template}'::text[]);
    IF stand IS DISTINCT FROM 'actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_descendant_edge,actor_descendants,actor_evaluation,actor_fact,actor_fact_current,actor_fact_current_pointer,actor_fact_current_v2,actor_fact_history,actor_location,actor_merge_log,actor_person,actor_ranking,actor_read,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event,hub_actor,hub_actor_removed' THEN
        RAISE EXCEPTION '800 refused: the actor stand-ins differ from the reviewed ones: %', stand;
    END IF;
    SELECT string_agg(proname || '=' || md5(replace(prosrc, chr(13) || chr(10), chr(10))), ' ' ORDER BY proname) INTO fns
      FROM pg_proc WHERE pronamespace = 'public'::regnamespace
       AND proname = ANY ('{ghus_guard_organization_status,ghus_guard_ranking_is_university,ghus_guard_subscription_run_append_only,ghus_organization_details_on_pointer,ghus_organization_details_on_topicless_fact,ghus_organization_details_refresh,ghus_prevent_organization_family_cycle,ghus_project_organization_verification_status,ghus_validate_entity_edge}'::text[]);
    IF fns IS DISTINCT FROM 'ghus_guard_organization_status=79ee4a866301ac87769c082b71834614 ghus_guard_ranking_is_university=6fdd630187f7bffbb46b5bc8574072a7 ghus_guard_subscription_run_append_only=575a4cdc05eb3a2995807307762a5329 ghus_organization_details_on_pointer=505ffe75c4ede1521ddf7d0309a91839 ghus_organization_details_on_topicless_fact=505ffe75c4ede1521ddf7d0309a91839 ghus_organization_details_refresh=42ed8b4a7b5e6350fb380ca6a2bd412d ghus_prevent_organization_family_cycle=d26dc6562cd14ebdc4ee8bf921cf95ee ghus_project_organization_verification_status=6937f673c34fd81e45219e89e7bc75c7 ghus_validate_entity_edge=d1594c2919f6088793ab4c643a3874f2' THEN
        RAISE EXCEPTION '800 refused: functions differ from the reviewed ones: %', fns;
    END IF;
END $guard$;

-- Saved for the rollback: the functions as they are, and the stand-ins.
INSERT INTO compass.migration_snapshot (migration_id, object_name, definition)
SELECT '800', 'function:' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
       pg_get_functiondef(p.oid)
  FROM pg_proc p
 WHERE p.pronamespace = 'public'::regnamespace AND p.proname = ANY ('{ghus_guard_organization_status,ghus_guard_ranking_is_university,ghus_guard_subscription_run_append_only,ghus_organization_details_on_pointer,ghus_organization_details_on_topicless_fact,ghus_organization_details_refresh,ghus_prevent_organization_family_cycle,ghus_project_organization_verification_status,ghus_validate_entity_edge}'::text[]);
INSERT INTO compass.migration_snapshot (migration_id, object_name, definition)
SELECT '800', 'standin:' || c.relname, pg_get_viewdef(c.oid)
  FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind = 'v'
   AND c.relname = ANY ('{actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_descendant_edge,actor_descendants,actor_evaluation,actor_fact,actor_fact_current,actor_fact_current_pointer,actor_fact_current_v2,actor_fact_history,actor_location,actor_merge_log,actor_person,actor_ranking,actor_read,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event,hub_actor,hub_actor_removed}'::text[]);

