-- 4. Constraint, index, trigger and policy names on them that say organization.
DO $names$
DECLARE r record; target text;
BEGIN
    FOR r IN SELECT c.conname AS old, cl.relname AS rel
               FROM pg_constraint c JOIN pg_class cl ON cl.oid = c.conrelid
              WHERE c.connamespace = 'public'::regnamespace AND c.conname LIKE '%organization%'
                AND cl.relname = ANY ('{hub_actor,hub_actor_removed,actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_evaluation,actor_fact,actor_fact_current_pointer,actor_location,actor_merge_log,actor_person,actor_ranking,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event}'::text[]) LOOP
        target := replace(r.old, 'organization', 'actor');
        EXECUTE format('ALTER TABLE public.%I RENAME CONSTRAINT %I TO %I', r.rel, r.old, target);
        INSERT INTO _renames VALUES ('constraint', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT i.relname AS old, t.relname AS rel
               FROM pg_index x JOIN pg_class i ON i.oid = x.indexrelid JOIN pg_class t ON t.oid = x.indrelid
              WHERE t.relnamespace = 'public'::regnamespace AND i.relname LIKE '%organization%'
                AND t.relname = ANY ('{hub_actor,hub_actor_removed,actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_evaluation,actor_fact,actor_fact_current_pointer,actor_location,actor_merge_log,actor_person,actor_ranking,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event}'::text[]) LOOP
        target := replace(r.old, 'organization', 'actor');
        EXECUTE format('ALTER INDEX public.%I RENAME TO %I', r.old, target);
        INSERT INTO _renames VALUES ('index', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT tg.tgname AS old, c.relname AS rel
               FROM pg_trigger tg JOIN pg_class c ON c.oid = tg.tgrelid
              WHERE NOT tg.tgisinternal AND c.relnamespace = 'public'::regnamespace
                AND tg.tgname LIKE '%organization%' AND c.relname = ANY ('{hub_actor,hub_actor_removed,actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_evaluation,actor_fact,actor_fact_current_pointer,actor_location,actor_merge_log,actor_person,actor_ranking,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event}'::text[]) LOOP
        target := replace(r.old, 'organization', 'actor');
        EXECUTE format('ALTER TRIGGER %I ON public.%I RENAME TO %I', r.old, r.rel, target);
        INSERT INTO _renames VALUES ('trigger', r.rel, r.old, target);
    END LOOP;
    FOR r IN SELECT p.policyname AS old, p.tablename AS rel FROM pg_policies p
              WHERE p.schemaname = 'public' AND p.policyname LIKE '%organization%'
                AND p.tablename = ANY ('{hub_actor,hub_actor_removed,actor,actor_category_definition,actor_category_migration_audit,actor_category_type_definition,actor_evaluation,actor_fact,actor_fact_current_pointer,actor_location,actor_merge_log,actor_person,actor_ranking,actor_relevance,actor_sector,actor_strategic_connection_check,actor_topic,actor_update_subscription,actor_update_subscription_run,actor_verification_event}'::text[]) LOOP
        target := replace(r.old, 'organization', 'actor');
        EXECUTE format('ALTER POLICY %I ON public.%I RENAME TO %I', r.old, r.rel, target);
        INSERT INTO _renames VALUES ('policy', r.rel, r.old, target);
    END LOOP;
END $names$;

-- 5. Functions: the ones named organization are dropped and created again under the actor
--    name (a parameter name cannot change in place); the others get their new body.
--    Triggers call them by name inside their bodies, so the order does not matter here.
CREATE TEMP TABLE _fn_triggers ON COMMIT DROP AS
SELECT tg.tgname, c.relname, p.proname,
       pg_get_triggerdef(tg.oid) AS def
  FROM pg_trigger tg JOIN pg_class c ON c.oid = tg.tgrelid JOIN pg_proc p ON p.oid = tg.tgfoid
 WHERE NOT tg.tgisinternal AND p.pronamespace = 'public'::regnamespace AND p.proname = ANY ('{ghus_guard_organization_status,ghus_organization_details_on_pointer,ghus_organization_details_on_topicless_fact,ghus_organization_details_refresh,ghus_prevent_organization_family_cycle,ghus_project_organization_verification_status}'::text[]);
DO $drop_triggers$
DECLARE t record;
BEGIN
    FOR t IN SELECT * FROM _fn_triggers LOOP
        EXECUTE format('DROP TRIGGER %I ON public.%I', t.tgname, t.relname);
    END LOOP;
END $drop_triggers$;
